import XCTest

@MainActor final class UpcomingGameReviewJourneyTests:XCTestCase {
    private func tap(_ id:String,_ app:XCUIApplication){let b=app.buttons[id];XCTAssertTrue(b.waitForExistence(timeout:15));for _ in 0..<18 where !b.isHittable{app.swipeUp(velocity:.slow)};XCTAssertTrue(b.isHittable);b.tap()}
    private func path(_ app:XCUIApplication){tap("productMenu",app);tap("productModeMenu",app);tap("productMode-path",app);openPlacedBeginnerCourse(app)}
    private func fullScreenGame(_ app:XCUIApplication){let map=app.otherElements["rpgWorld"];XCTAssertTrue(map.waitForExistence(timeout:20));let ready=XCTNSPredicateExpectation(predicate:NSPredicate{_,_ in let frame=map.frame,bounds=app.frame;return map.exists && frame.minY<=bounds.minY+1 && frame.maxY>=bounds.maxY-1 && frame.width>=bounds.width-1},object:nil);XCTAssertEqual(XCTWaiter.wait(for:[ready],timeout:15),.completed,"The game must finish presenting across the entire phone display")}
    private func shot(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
    func testQuizCompletionWarmsTheImmediateReviewAndRelaunchUsesItWithoutAProvider(){
        continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_PRACTICE_FIXTURE":"delight:natural_or_weird","PIYALI_RPG_PREPARED_FIXTURE":"prepared","PIYALI_RPG_PREPARED_DELAY_MS":"0","PIYALI_GAME_LOADER_SEED":"7"]
        app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US","-piyali.interfaceLanguage","en","-piyali.theme","light"];app.launch();handleInitialPaperPencil(app)
        let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Review Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);tap("startLearning",app);tap("companionContinue",app);acknowledgePaperPencil(app);tap("gettingStartedGotIt",app);chooseA1Placement(app);path(app)
        tap("lessonNode-lesson-pre-a1-1-quiz",app);tap("startLessonFromPreview",app);XCTAssertTrue(app.staticTexts["quizProgress"].waitForExistence(timeout:15))
        for index in 1...8{tap("typedChoice-0",app);tap("checkTypedAnswer",app);if index<8{tap("nextTypedQuestion",app)}}
        XCTAssertTrue(app.staticTexts["quizResult"].waitForExistence(timeout:10));shot("Native upcoming review quiz passed",app);tap("quizExit",app);XCTAssertTrue(app.staticTexts["lessonCompletionBonus"].waitForExistence(timeout:15));XCTAssertEqual(app.staticTexts["lessonCompletionBonus"].label,"+80");XCTAssertFalse(app.otherElements["rpgWorld"].exists);shot("Native upcoming review warms behind quiz acknowledgment",app)
        tap("continueLessonCompletion",app);continueLessonFollowups(app);let node=app.buttons["lessonNode-unit-pre-a1-people-game"];XCTAssertTrue(node.waitForExistence(timeout:15));XCTAssertTrue(node.isEnabled);shot("Native upcoming review remains unstarted on path",app)
        app.terminate();app.launchEnvironment["PIYALI_RPG_PREPARED_FIXTURE"]="cache-only";app.launch();handleInitialPaperPencil(app);path(app);tap("lessonNode-unit-pre-a1-people-game",app);tap("startLessonFromPreview",app);XCTAssertTrue(app.otherElements["gamePreparationWorld"].waitForExistence(timeout:8));shot("Native warmed review keeps source exploration window",app);fullScreenGame(app);XCTAssertTrue(app.descendants(matching:.any)["rpgStatus"].label.contains("0/7"));XCTAssertFalse(app.staticTexts["lessonCompletionBonus"].exists);shot("Native warmed review opens seven beats without provider",app)
        tap("rpgBack",app);app.terminate();app.launch();handleInitialPaperPencil(app);path(app);tap("lessonNode-unit-pre-a1-people-game",app);tap("startLessonFromPreview",app);fullScreenGame(app);XCTAssertTrue(app.descendants(matching:.any)["rpgStatus"].label.contains("0/7"));XCTAssertFalse(app.staticTexts["lessonCompletionBonus"].exists);shot("Native warmed review saved run resumes after relaunch",app)
    }
}
